'use strict';
const $=id=>document.getElementById(id),C=FloodCore,colors=['#9aa9ad','#77bfa5','#b5cb69','#e7bb42','#ec8354','#bd4869'],names=['Sem cobertura','Muito baixo','Baixo','Médio','Alto','Muito alto'],pressNames=['Sem dados','Reduzida','Moderada','Elevada','Muito elevada'];
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=(n,d=1)=>n===null||n===undefined?'n.d.':Number(n).toLocaleString('pt-PT',{maximumFractionDigits:d}),date=s=>s?new Date(s).toLocaleString('pt-PT',{timeZone:'Europe/Lisbon',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})+' PT':'sem medição';
let data={},map,selected=null,basinState=new Map(),stationMap=new Map(),reloadBusy=false;
async function get(n){let v='?v='+Math.floor(Date.now()/60000);if(n.endsWith('.geojson')&&typeof DecompressionStream!=='undefined'){try{let r=await fetch('data/'+n+'.gz'+v);if(r.ok)return await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).json();}catch{}}let r=await fetch('data/'+n+v);if(!r.ok)throw Error(n+' indisponível');return r.json();}
function stationFresh(s){return C.fresh(s.properties.observed_at);}
function compute(){stationMap=new Map(data.stations.features.map(s=>[s.properties.id,s]));basinState.clear();for(let b of data.basins.features){let within=data.stations.features.filter(s=>stationFresh(s)&&turf.booleanPointInPolygon(s,b));let newest=within.map(s=>s.properties.observed_at).sort().at(-1);let synchronized=within.filter(s=>s.properties.observed_at===newest);const mean=k=>{let rows=synchronized.filter(s=>s.properties[k]!==null);return rows.length?rows.reduce((v,s)=>v+s.properties[k],0)/rows.length:null;};let p1=mean('p1'),p6=mean('p6'),p24=mean('p24');let complete=synchronized.filter(s=>['p1','p6','p24'].every(k=>s.properties[k]!==null));let pressure=complete.length>=2?C.rainPressure(...['p1','p6','p24'].map(k=>complete.reduce((a,s)=>a+s.properties[k],0)/complete.length)):null;let v={...b.properties,p1,p6,p24,pressure,n:synchronized.length,n_complete:complete.length,observed_at:newest,stations:synchronized.map(s=>s.properties.id),area_km2:turf.area(b)/1e6};basinState.set(String(b.properties.objectid),v);Object.assign(b.properties,{pressure,stations_count:v.n});}
for(let f of data.parishes.features){let p=f.properties,states=p.basin_ids.map(id=>basinState.get(id)).filter(Boolean);let valid=states.filter(s=>s.pressure!==null);p.pressure=valid.length?Math.max(...valid.map(s=>s.pressure)):null;p.priority=p.pressure===null||p.scenario_risk===null?null:Math.max(1,Math.min(4,Math.ceil((p.pressure+p.scenario_risk)/2)));p.current_risk=null;}
$('station-count').textContent=data.stations.features.filter(stationFresh).length;$('parish-count').textContent=data.parishes.features.filter(f=>f.properties.scenario_risk!==null).length;
const latest=data.stations.features.map(s=>s.properties.observed_at).filter(Boolean).sort().at(-1);$('updated').textContent='IPMA '+date(latest)+' · consulta '+date(data.stations.retrieved_at);}
function value(p){return p[$('view').value==='scenario'?'scenario_risk':$('view').value];}
function color(v){return v==null?colors[0]:$('view').value==='scenario'?colors[v]:['',colors[1],colors[3],colors[4],colors[5]][v];}
function label(v){return v==null?($('view').value==='scenario'?'Sem cobertura':'Por determinar'):$('view').value==='scenario'?names[v]:$('view').value==='pressure'?pressNames[v]:['','Reduzida','Moderada','Elevada','Muito elevada'][v];}
function render(){if(!data.parishes)return;let q=$('search').value.toLocaleLowerCase('pt-PT'),rows=data.parishes.features.filter(f=>(f.properties.freguesia+' '+f.properties.municipio).toLocaleLowerCase('pt-PT').includes(q));rows.sort((a,b)=>(value(b.properties)??-1)-(value(a.properties)??-1)||(b.properties.population_2021??0)-(a.properties.population_2021??0));$('result-count').textContent=rows.length.toLocaleString('pt-PT');$('results').innerHTML=rows.slice(0,70).map(f=>{let p=f.properties,v=value(p);return `<button class="result" data-code="${E(p.dtmnfr)}"><span class="badge" style="background:${color(v)}35;color:#17323b">${E(label(v))}</span><strong>${E(p.freguesia)}</strong><small>${E(p.municipio)} · ${num(p.population_2021,0)} residentes</small></button>`;}).join('')||'<p>Sem resultados.</p>';
let title=$('view').value==='scenario'?'Risco de inundação APA · T100':$('view').value==='pressure'?'Pressão da chuva nas bacias':'Prioridade de análise';let n=$('view').value==='scenario'?5:4;$('legend').innerHTML=`<b>${title}</b>`+Array.from({length:n},(_,i)=>`<div class="legend-row"><i class="swatch" style="background:${color(i+1)}"></i>${label(i+1)}</div>`).join('')+`<div class="legend-row"><i class="swatch" style="background:${colors[0]}"></i>${label(null)}</div><small>${$('view').value==='scenario'?'Cenário com período de retorno de 100 anos. Não representa a cheia atual.':'Indicador experimental; mínimo de 2 estações na bacia com 1/6/24 h completas. Não é aviso oficial.'}</small>`;
if(map?.getSource('parishes')){map.getSource('parishes').setData(data.parishes);let key=$('view').value==='scenario'?'scenario_risk':$('view').value;let expression=['match',['coalesce',['get',key],0],0,colors[0]];for(let i=1;i<=n;i++)expression.push(i,color(i));expression.push(colors[0]);map.setPaintProperty('parishes-fill','fill-color',expression);}}
function metric(k,v){return `<dt>${E(k)}</dt><dd>${v}</dd>`;}
function showParish(code,fly=true){let f=data.parishes.features.find(f=>f.properties.dtmnfr===code);if(!f)return;selected=code;let p=f.properties;let states=p.basin_ids.map(id=>basinState.get(id)).filter(Boolean).sort((a,b)=>(b.pressure??-1)-(a.pressure??-1));let b=states[0];$('detail-content').innerHTML=`<div class="eyebrow">FREGUESIA · CAOP2025 · ${E(code)}</div><h2>${E(p.freguesia)}</h2><p>${E(p.municipio)} · ${E(p.distrito_ilha)}</p><h3>Cenário de risco APA · T100</h3><span class="badge" style="background:${colors[p.scenario_risk||0]}40">${p.scenario_risk===null?'Sem cobertura neste cenário':names[p.scenario_risk]}</span><p>${p.scenario_risk!==null?'Classe máxima que intersecta a freguesia. Não se aplica uniformemente a todo o território. Locais APA: '+E(p.scenario_sites.join(', '))+'.':'A ausência de interseção com esta cartografia não demonstra ausência de perigo.'}</p><h3>População residente</h3><strong class="big">${num(p.population_2021,0)}</strong><p>Censos 2021 · INE 0014584, apurados para a geografia de freguesias de 2025.</p><dl>${metric('Pessoas expostas à cheia atual','Por determinar')}${metric('Pessoas vulneráveis','Por determinar')}${metric('Mobilidade reduzida / dependência','Dados por integrar')}</dl><p>O total de residentes não equivale a pessoas afetadas. A exposição precisa de mancha de inundação e dados populacionais de maior detalhe; idade, isolamento, mobilidade e equipamentos devem ser considerados.</p><h3>Pressão meteorológica nas bacias</h3><dl>${metric('Bacias intersectadas',String(states.length))}${metric('Pressão máxima',p.pressure===null?'Por determinar':pressNames[p.pressure])}${metric('Prioridade de análise',p.priority===null?'Por determinar':['','Reduzida','Moderada','Elevada','Muito elevada'][p.priority])}</dl><p>Usa a maior pressão de uma bacia que intersecta a freguesia. É uma triagem; não demonstra ligação hidráulica a todas as suas zonas.</p>${b?basinHTML(b):''}<h3>Rios e barragens</h3><p>${E(data.hydrology.note||'Consultar camadas de estações e barragens para observações disponíveis.')} Estado da ligação: ${E(data.hydrology.status)}.</p><a href="https://snirh.apambiente.pt/" target="_blank" rel="noopener">Consultar SNIRH ↗</a>`;$('detail').hidden=false;bindRunoff(b);if(fly){let box=turf.bbox(f);map.fitBounds([[box[0],box[1]],[box[2],box[3]]],{padding:65,maxZoom:12});}}
function basinHTML(b){return `<h3>Bacia APA #${E(b.objectid)}</h3><dl>${metric('Área representada',num(b.area_km2)+' km²')}${metric('Estações / séries completas',b.n+' / '+b.n_complete)}${metric('Hora comum',date(b.observed_at))}${metric('Chuva média 1 h',num(b.p1)+' mm')}${metric('Chuva média 6 h',num(b.p6)+' mm')}${metric('Chuva média 24 h',num(b.p24)+' mm')}</dl><p>Média simples das estações dentro da bacia com a mesma hora, por janela disponível. Não é precipitação areal validada. Não usa estações de outra bacia para preencher falhas.</p><details><summary>Explorar escoamento · cenário não calibrado</summary><p>SCS-CN, abstração inicial 0,2S. Aplique apenas como análise de sensibilidade: não prevê nível, caudal de ponta nem mancha inundada.</p><label for="cn">Curve Number: <span id="cn-value">75</span></label><input id="cn" type="range" min="30" max="98" value="75"><dl id="runoff-output"></dl><p>Volume de escoamento gerado na área representada em 24 h, sem propagação, trânsito de cheia, barragens ou contribuições de Espanha. CN deve ser derivado de solo, ocupação e humidade antecedente e calibrado por bacia.</p></details>`;}
function bindRunoff(b){if(!b||!$('cn'))return;const calc=()=>{let cn=Number($('cn').value);$('cn-value').textContent=cn;let q=C.runoff(b.p24,cn),v=C.volume(q,b.area_km2);$('runoff-output').innerHTML=metric('Escoamento superficial',num(q)+' mm')+metric('Volume gerado',v===null?'n.d.':num(v/1e6,3)+' hm³');};$('cn').oninput=calc;calc();}
function stationPopup(f){let p=f.properties,fresh=stationFresh(f);let rows=p.rows||[],max=Math.max(1,...rows.map(r=>r.mm||0));return `<b>${E(p.name)}</b><p>IPMA · ${date(p.observed_at)}<br>${fresh?'Observação recente':'Dados antigos ou sem observação'}</p><dl>${metric('Última hora',num(p.p1)+' mm')}${metric('6 horas completas',num(p.p6)+' mm')}${metric('24 horas completas',num(p.p24)+' mm')}</dl><div class="chart">${rows.map(r=>`<div class="${r.mm===null?'missing':''}" title="${E(date(r.time))}: ${num(r.mm)} mm" style="height:${Math.max(3,(r.mm||0)/max*100)}%"></div>`).join('')}</div><p>Chuva horária · cinzento = medição em falta. Acumulados incompletos ficam n.d.</p>`;}
function mapInit(){map=new maplibregl.Map({container:'map',center:[-8,39.7],zoom:6.2,style:{version:8,sources:{base:{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,attribution:'© OpenStreetMap contributors'}},layers:[{id:'base',type:'raster',source:'base'}]}});map.addControl(new maplibregl.NavigationControl(),'top-right');map.on('load',()=>{for(let n of ['parishes','basins','risk','hydro_catalogue','dams','stations'])map.addSource(n,{type:'geojson',data:data[n]});map.addLayer({id:'parishes-fill',type:'fill',source:'parishes',paint:{'fill-color':colors[0],'fill-opacity':.32}});map.addLayer({id:'parishes-line',type:'line',source:'parishes',paint:{'line-color':'#526e73','line-width':.45,'line-opacity':.5}});map.addLayer({id:'risk',type:'fill',source:'risk',paint:{'fill-color':['match',['get','risco'],'Muito Alto',colors[5],'Alto',colors[4],'Médio',colors[3],'Baixo',colors[2],colors[1]],'fill-opacity':.7}});map.addLayer({id:'basins',type:'line',source:'basins',paint:{'line-color':'#228d9e','line-width':1.2,'line-opacity':.65}});map.addLayer({id:'hydro',type:'circle',source:'hydro_catalogue',layout:{visibility:'none'},paint:{'circle-radius':4,'circle-color':'#704ea5','circle-stroke-width':1,'circle-stroke-color':'white'}});map.addLayer({id:'dams',type:'circle',source:'dams',layout:{visibility:'none'},paint:{'circle-radius':5,'circle-color':'#173c65','circle-stroke-width':2,'circle-stroke-color':'white'}});map.addLayer({id:'rain',type:'circle',source:'stations',paint:{'circle-radius':['interpolate',['linear'],['coalesce',['get','p1'],0],0,3,5,6,20,10,50,14],'circle-color':['case',['==',['get','fresh'],false],'#9ba8ad',['interpolate',['linear'],['coalesce',['get','p1'],0],0,'#3ba7b7',10,'#e8b83d',30,'#c64762']],'circle-stroke-width':1.4,'circle-stroke-color':'white','circle-opacity':.92}});map.on('click',e=>{let hits=map.queryRenderedFeatures(e.point,{layers:['rain','hydro','dams','parishes-fill']});let hit=hits[0];if(!hit)return;if(hit.layer.id==='parishes-fill'){showParish(hit.properties.dtmnfr,false);return;}let html;if(hit.layer.id==='rain'){let f=stationMap.get(hit.properties.id);html=stationPopup(f);}else if(hit.layer.id==='dams'){let p=hit.properties;let row=data.hydrology.reservoirs.find(x=>String(x.id)===String(p.id))||data.bulletin?.records.filter(x=>x.catalogue_id===String(p.id)).sort((a,b)=>b.reference_period.localeCompare(a.reference_period))[0];html=`<b>${E(p.albufeira)}</b><p>${E(p.lagua)} · ${E(p.bacia)}</p>`+(row?`<p>Armazenamento: ${num(row.storage_hm3)} hm³<br>Descarga: ${num(row.outflow_m3s)} m³/s<br>${E(row.reference_period||date(row.observed_at))} · ${row.temporal_resolution?'boletim, não telemetria':C.fresh(row.observed_at)?'recente':'antigo'}</p>`:'<p>Armazenamento / enchimento / descarga atual: sem medição ligada. O ponto é um catálogo estático APA.</p>');}else{let p=hit.properties;let row=data.hydrology.rivers.find(x=>String(x.id)===String(p.codigo));html=`<b>${E(p.nome)}</b><p>Código ${E(p.codigo)} · ${E(p.estado)}</p>`+(row?`<p>Nível: ${num(row.level_m)} m<br>Caudal: ${num(row.flow_m3s)} m³/s<br>${E(row.reference_period||date(row.observed_at))} · ${row.temporal_resolution?'boletim, não telemetria':C.fresh(row.observed_at)?'recente':'antigo'}</p>`:'<p>Nível e caudal atual: sem telemetria ligada. Catálogo estático APA.</p>');}new maplibregl.Popup().setLngLat(e.lngLat).setHTML(html).addTo(map);});render();});map.on('error',e=>{if(e.error?.message?.includes('Failed to fetch'))console.warn('Camada temporariamente indisponível');});}
function methodHTML(){return `<h3>1. Risco territorial oficial, por cenário</h3><p>O mapa usa a camada <a href="https://sniambgeoogc.apambiente.pt/getogc/rest/services/SNIAmb/Diretiva200760CE_2c/MapServer/5" target="_blank" rel="noopener">APA — Diretiva 2007/60/CE, 2.º ciclo</a>, para o período de retorno de 100 anos. A freguesia recebe a classe máxima dos polígonos intersectados; não se interpreta como risco homogéneo. Fora das áreas estudadas o risco fica desconhecido. T100 corresponde a um cenário estatístico de planeamento, não à data prevista da próxima cheia.</p><h3>2. Matriz de risco de cheia</h3><p>Referência histórica APA, REA2016: combinação de intensidade e consequências, cinco classes. Intensidade RI = d × (v + 0,5), com d em metros e v em m/s. Limiares: &lt;0,75; 0,75–1,25; 1,25–2,5; 2,5–7; &gt;7. Os limites exatos são uma convenção desta implementação demonstrativa. A camada do 2.º ciclo é apresentada com a classificação publicada pela APA, sem a recalcular com esta matriz histórica.</p><table><thead><tr><th>Consequência ↓ / intensidade →</th>${[1,2,3,4,5].map(n=>'<th>'+n+'</th>').join('')}</tr></thead><tbody>${C.matrix.map((row,i)=>'<tr><th>'+(i+1)+'</th>'+row.map(n=>'<td style="background:'+colors[n]+'35">'+names[n]+'</td>').join('')+'</tr>').join('')}</tbody></table><p><a href="https://sniambgeoviewer.apambiente.pt/Geodocs/geoportaldocs/rea/REA2016/REA2016.pdf" target="_blank" rel="noopener">Fonte histórica: APA, REA2016, p.197 ↗</a>. Não é usada para deduzir profundidade/velocidade a partir de chuva.</p><h3>3. Pressão da chuva e prioridade · método experimental</h3><p><a href="https://api.ipma.pt/" target="_blank" rel="noopener">IPMA</a>: precipitação acumulada da hora, −99 convertido para dados em falta; acumulados de 6/24 h exigem todas as horas. Observações recentes até 3 h; futuras &gt;6 min rejeitadas. A recolha no GitHub corre a cada 15 min e o navegador consulta a cada 5 min, mas a fonte é horária e o agendamento pode atrasar.</p><p>Na bacia, exige-se um mínimo de duas estações interiores, sincronizadas na mesma hora, com séries completas. Média simples; sem interpolação espacial ou chuva espanhola. Pressão: reduzida abaixo dos limiares; moderada se ≥10/25/40 mm em 1/6/24 h; elevada ≥20/50/80; muito elevada ≥30/80/120. São limiares exploratórios próprios, não avisos IPMA nem probabilidades de cheia. Prioridade = teto da média das classes de pressão e risco T100, limitada a 1–4. Sem qualquer componente fica por determinar.</p><h3>4. Escoamento por bacia</h3><p>SCS-CN: S=25400/CN−254; Ia=0,2S; Q=(P−Ia)²/(P+0,8S) para P&gt;Ia, senão 0. Volume=Q(mm)×área(km²)×1000 m³. A ferramenta deixa variar CN apenas como cenário. Falta calibração por solos, ocupação, humidade antecedente, propagação na rede fluvial e operação de barragens. Não há previsão de caudal de ponta, altura ou tempo de chegada. <a href="https://directives.nrcs.usda.gov/sites/default/files2/1712930592/Chapter%2010%20-%20Estimation%20of%20Direct%20Runoff%20from%20Storm%20Rainfall.pdf" target="_blank" rel="noopener">NRCS — Direct Runoff ↗</a></p><h3>5. População e vulnerabilidade</h3><p>DGT CAOP2025 e INE indicador 0014584, Censos2021 na geografia2025, unidos pelo código DTMNFR. Os residentes são uma contagem censitária da freguesia, não pessoas presentes em tempo real nem pessoas inundadas. A população exposta e os grupos vulneráveis ficam n.d. enquanto não estiverem ligados dados BGRI/edifícios, idades, mobilidade, isolamento e equipamentos com interseção na mancha. Não se atribuem percentagens inventadas.</p><h3>6. Rios e barragens: estado real da ligação</h3><p>O SNIRH publica séries e boletins com diferentes cadências. Os catálogos APA mostram localização e características, não garantem medições atuais. Neste lançamento, o fluxo automático de níveis, caudais, armazenamento e descargas está por ligar. Um feed autorizado pode ser integrado com hora por observação e proveniência. Enchimento elevado, isoladamente, não significa maior risco a jusante: importam afluências, descargas e regras de exploração.</p><p>Este observatório experimental apoia análise. A emissão de alertas operacionais exige validação histórica e acompanhamento de avisos oficiais IPMA, APA e Proteção Civil.</p>`;}
async function reload(){if(reloadBusy)return;reloadBusy=true;$('refresh').disabled=true;try{let [s,h,st]=await Promise.all([get('stations.geojson'),get('hydrology.json'),get('status.json')]);data.stations=s;data.hydrology=h;data.status=st;for(let f of s.features)f.properties.fresh=stationFresh(f);compute();map?.getSource('stations')?.setData(s);render();if(selected)showParish(selected,false);if(st.failures.length)$('updated').textContent+=' · falha na recolha: '+st.failures.join('; ');}catch(e){$('updated').textContent='Não foi possível atualizar. Os dados mantêm as horas originais.';}finally{reloadBusy=false;$('refresh').disabled=false;}}
async function init(){try{let keys=['parishes','basins','risk','hydro_catalogue','dams','stations'];let entries=await Promise.all(keys.map(async k=>[k,await get(k+'.geojson')]));data=Object.fromEntries(entries);data.hydrology=await get('hydrology.json');for(let s of data.stations.features)s.properties.fresh=stationFresh(s);compute();render();mapInit();map.once('load',()=>{enhance().then(()=>loadStudies()).then(()=>Promise.allSettled([loadHydraulics(),loadTelemetry()])).catch(e=>{$('updated').textContent+=' · estudo indisponível: '+e.message;console.warn(e);});});$('method-content').innerHTML=methodHTML();$('method-button').onclick=()=>$('method').showModal();$('close-method').onclick=()=>$('method').close();$('close-detail').onclick=()=>{$('detail').hidden=true;selected=null;};$('results').onclick=e=>{let b=e.target.closest('[data-code]');if(b)showParish(b.dataset.code);};$('search').oninput=render;$('view').onchange=render;$('refresh').onclick=reload;$('home').onclick=()=>map.fitBounds([[-9.6,36.8],[-6.1,42.2]],{padding:40});document.querySelectorAll('[data-layer]').forEach(c=>c.onchange=()=>map.setLayoutProperty(c.dataset.layer,'visibility',c.checked?'visible':'none'));setInterval(()=>{if(!document.hidden)reload();},300000);}catch(e){$('updated').textContent='Falha ao carregar dados';$('map-error').hidden=false;$('map-error').textContent='Não foi possível carregar o observatório: '+e.message;console.error(e);}}
init();

